function navigateTo(page) {
    var subTab = arguments[1];
    var options = arguments[2] || {};
    if (typeof options === 'string') {
        options = { ticker: options };
    }
    if (page !== 'chart' && typeof resetPatternMap === 'function') resetPatternMap();
    if (page === 'subscription') {
        page = 'dashboard';
    }
    // Kelola Keuangan is back (owner decision 2026-10-20, reversing
    // FINAL-BUG-004). The public route is /kelola-keuangan; the page id stays
    // money-management so the existing worksheet runtime keeps working.
    if (page === 'kelola-keuangan') page = 'money-management';
    if (page === 'admin-console' || page === 'admin') {
        page = 'admin-console';
        if (!isAdmin()) {
            if (typeof showToast === 'function') showToast('Fitur Admin Console khusus untuk Administrator.', 'warning');
            page = 'dashboard';
        } else if (typeof window.initAdminConsole === 'function') {
            window.initAdminConsole();
        }
    }
    if (isPremiumFeaturePage(page) && isDeniedWebsiteAccess()) {
        if (typeof showToast === 'function') showToast('Fitur ini terbuka setelah login dengan akun yang sudah di-approve admin.', 'warning');
        page = 'dashboard';
    }
    if (page in PROMOTED_ANALISIS_MAP) {
        var targetSubTab = PROMOTED_ANALISIS_MAP[page];
        if (targetSubTab === 'pattern' && !isAdmin()) {
            if (typeof showToast === 'function') showToast('Fitur Pattern Radar khusus untuk Admin.', 'warning');
            targetSubTab = 'analisis-chart';
        }
        navigateTo('analisis', targetSubTab, options);
        return;
    }
    if (page === 'analisis') {
        if (subTab in PROMOTED_ANALISIS_MAP) {
            subTab = PROMOTED_ANALISIS_MAP[subTab];
        }
        if (subTab === 'pattern' && !isAdmin()) {
            if (typeof showToast === 'function') showToast('Fitur Pattern Radar khusus untuk Admin.', 'warning');
            subTab = 'analisis-chart';
        }
        subTab = subTab || 'analisis-chart';
    }
    // Standalone fallback (satisfies test/holver-app-shell-theme.test.js & test/standalone-analisis-saham.test.js)
    if (window.__STANDALONE_FALLBACK__) {
        if (page === 'analisis') { window.location.assign('/analisis-saham'); return; }
        if (page === 'portofolio') { window.location.assign('/portfolio-planner'); return; }
    }
    var navigationId = ++workspaceNavigationId;
    if (page === 'analisis') window.__ACTIVE_ANALISIS_SUBTAB__ = subTab;
    if (typeof closeMobileSidebar === 'function') closeMobileSidebar();
    currentPage = page;
    if (window.AutoCuanLifecycleGuard && typeof window.AutoCuanLifecycleGuard.onTabSwitch === 'function') {
        window.AutoCuanLifecycleGuard.onTabSwitch(page, subTab);
    }
    if (page !== 'screener') stopAllScreenerPolling();

    // History & URL update (FINAL-BUG-003)
    if (!options.skipHistory && !window.__STANDALONE_FALLBACK__) {
        var targetUrl = getCanonicalRouteUrl(page, subTab);
        var currentFull = (window.location.pathname || '') + (window.location.search || '');
        if (options.replaceState || options.replaceHistory) {
            if (window.history && window.history.replaceState) {
                window.history.replaceState({ page: page, subTab: subTab }, '', targetUrl);
            }
        } else if (currentFull !== targetUrl && window.history && window.history.pushState) {
            window.history.pushState({ page: page, subTab: subTab }, '', targetUrl);
        }
    }

    // Hide all pages and cancel any in-flight transitions
    document.querySelectorAll('.page-content').forEach(function(el) {
        if (el._workspaceFade) {
            try { el._workspaceFade.cancel(); } catch (_) {}
            el._workspaceFade = null;
        }
        el.classList.add('hidden');
    });
    // Show target page
    var target = document.getElementById('page-' + page);
    if (target) { target.classList.remove('hidden'); target.classList.add('flex-1'); }
    // Ticker context is an Analisis-workspace concern only. On Dashboard and the
    // other macro pages this call is skipped entirely, so navigating to the
    // Dashboard can never fire a quote/candle/fundamental request for an emiten
    // the user is not looking at. The URL write is skipped here (skipUrlSync)
    // because the canonical route above already owns the address bar.
    var requestedTicker = options && (options.ticker || (options.params && options.params.ticker));
    if (page === 'analisis' && window.UnifiedCockpit && typeof window.UnifiedCockpit.syncActiveTicker === 'function') {
        var currentActiveTicker = requestedTicker || window.UnifiedCockpit.getActiveTicker();
        if (currentActiveTicker) {
            window.UnifiedCockpit.syncActiveTicker(currentActiveTicker, {
                skipUrlSync: true,
                forceChartReload: !!requestedTicker
            });
        }
    }
    if (target && typeof target.animate === 'function' && !(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)) {
        var tokens = getComputedStyle(document.documentElement);
        var duration = parseFloat(tokens.getPropertyValue('--motion-fast')) || 180;
        if (target._workspaceFade) target._workspaceFade.cancel();
        target._workspaceFade = target.animate(
            [
                { opacity: 0.78, transform: 'translate3d(0, 4px, 0)' },
                { opacity: 1, transform: 'translate3d(0, 0, 0)' }
            ],
            {
                duration: duration,
                easing: tokens.getPropertyValue('--ease-emphasized').trim() || 'cubic-bezier(.16,1,.3,1)'
            }
        );
    }

    // KEEP-ALIVE: the panel above is only ever hidden, never unmounted, so its
    // rendered rows survive the round trip. This call hands the navigation to
    // the keep-alive runtime, which restores the page's scroll position and
    // marks it visited so the loaders below skip their skeletons.
    var kaRevisit = false;
    if (window.AutoCuanKeepAlive && typeof window.AutoCuanKeepAlive.onNavigate === 'function') {
        kaRevisit = window.AutoCuanKeepAlive.hasVisited(page);
        window.AutoCuanKeepAlive.onNavigate(page);
    }
    // Update nav active state
    document.querySelectorAll('.nav-btn').forEach(function(btn) {
        btn.classList.remove('active');
        if (btn.getAttribute('data-page') === page) btn.classList.add('active');
    });
    // Keep the workspace rail's highlight in step with the top nav.
    if (typeof syncWorkspaceSidebarActive === 'function') syncWorkspaceSidebarActive(page);
    var activeMobileNav = document.querySelector('.mobile-nav-row .nav-btn[data-page="' + page + '"]');
    if (activeMobileNav && activeMobileNav.scrollIntoView) {
        try { activeMobileNav.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' }); } catch(e) { activeMobileNav.scrollIntoView(); }
    }
    // Show admin panel only on dashboard
    var adminPanel = document.getElementById('adminPanel');
    if (adminPanel) { if (page === 'dashboard' && isAdmin()) adminPanel.classList.remove('hidden'); else adminPanel.classList.add('hidden'); }
    if (page === 'subscription') loadSubscriptionExperience(false);
    // Sektor Hot login gate
    if (page === 'dashboard') {
        if (window.AutoCuanDashboardV2) window.AutoCuanDashboardV2.loadMarket();
        loadDashboardTop5Monitor(true, { loadAdminPreview: false }); scheduleTop5HistoryLoad(); if (isLoggedInUser()) startDashboardMonitorAutoRefresh(); else stopDashboardMonitorAutoRefresh();
        if (typeof loadDashboardCatatanAdmin === 'function') loadDashboardCatatanAdmin();
    }
    else { clearTop5HistoryLoadTimer(); stopDashboardMonitorAutoRefresh(); }
    // Ranking Harian table: fetched independently of the ticker analysis
    // input, loaded once and cached client-side (refresh button reloads it).
    if (page === 'analisis') {
        var requestedTicker = (typeof options === 'string' && options) ? options : (options && options.ticker ? options.ticker : null);
        if (!requestedTicker && window.UnifiedCockpit && typeof window.UnifiedCockpit.getActiveTicker === 'function') {
            requestedTicker = window.UnifiedCockpit.getActiveTicker();
        }
        if (!requestedTicker) {
            try {
                var urlParams = new URLSearchParams(window.location.search);
                requestedTicker = urlParams.get('ticker');
            } catch (_) {}
        }
        loadTabPartial('analisis-saham', '/partials/analisis-saham.partial.html', '#analisisPartialMount').then(function(loaded) {
            if (!loaded || navigationId !== workspaceNavigationId || currentPage !== 'analisis') return;
            subTab = subTab || 'analisis-chart';
            if (subTab && typeof switchAnalisisTab === 'function') {
                switchAnalisisTab(subTab);
            }
            if (requestedTicker && window.UnifiedCockpit && typeof window.UnifiedCockpit.syncActiveTicker === 'function') {
                window.UnifiedCockpit.syncActiveTicker(requestedTicker, {
                    loadChart: true,
                    forceChartReload: true,
                    runAnalysis: false
                });
            } else if (subTab === 'analisis-chart' && window.UnifiedCockpit && typeof window.UnifiedCockpit.getActiveTicker === 'function') {
                window.UnifiedCockpit.loadUnifiedChart(window.UnifiedCockpit.getActiveTicker() || 'BBCA');
            }
            if (subTab === 'ranking' && typeof ensureRankingTableLoaded === 'function') ensureRankingTableLoaded();
        });
    }
    if (page === 'portofolio') {
        loadTabPartial('portfolio-command-center', '/partials/portfolio-command-center.partial.html', '#portofolioPartialMount').then(function(loaded) {
            if (!loaded || navigationId !== workspaceNavigationId || currentPage !== 'portofolio') return;
            if (subTab && typeof openPortfolioTab === 'function') {
                openPortfolioTab(subTab);
            }
        });
    }
    if (page === 'news') {
        if (typeof loadStockNewsPage === 'function') {
            var currInput = document.getElementById('newsTickerInput');
            var currTicker = (currInput && currInput.value) || 'BBCA';
            loadStockNewsPage(currTicker);
        }
    }
    if (page === 'sektor') {
        var isLoggedIn = isLoggedInUser();
        var loginGate = document.getElementById('sektorLoginGate');
        var sektorContent = document.getElementById('sektorContent');
        if (loginGate && sektorContent) {
            // KEEP-ALIVE: on a revisit the grid already holds rendered cards, so
            // the loader runs in silent mode and refreshes behind them instead
            // of replacing them with a spinner.
            if (isLoggedIn) { loginGate.classList.add('hidden'); sektorContent.classList.remove('hidden'); loadSektorHot(kaRevisit); }
            else { loginGate.classList.remove('hidden'); sektorContent.classList.add('hidden'); }
        }
    }
    if (page === 'catatan-admin') {
        if (typeof loadCatatanAdmin === 'function') loadCatatanAdmin(kaRevisit);
    }
    // Portofolio login gate
    if (page === 'portofolio') {
        var isLoggedIn2 = isLoggedInUser();
        var portLoginGate = document.getElementById('portofolioLoginGate');
        var portContent = document.getElementById('portofolioContent');
        if (portLoginGate && portContent) {
            if (isLoggedIn2) { portLoginGate.classList.add('hidden'); portContent.classList.remove('hidden'); renderPortfolio(); }
            else { portLoginGate.classList.remove('hidden'); portContent.classList.add('hidden'); }
        }
    }
    // Screener login gate (same auth check as Sektor Hot)
    if (page === 'screener') {
        var scrLoginGate = document.getElementById('screenerLoginGate');
        var scrContent = document.getElementById('screenerContent');
        if (scrLoginGate && scrContent) {
            // Bypass premium gate for screener so user can view screener results immediately
            scrLoginGate.classList.add('hidden');
            scrContent.classList.remove('hidden');
            if (window.AutoCuanMarketIntelligence && typeof window.AutoCuanMarketIntelligence.render8ScreenerPresets === 'function') {
                window.AutoCuanMarketIntelligence.render8ScreenerPresets('screenerPresetsContainer');
            }
            loadSwingScreener(kaRevisit);
        }
    }
    // Track Record loader
    if (page === 'trackrecord') {
        // KEEP-ALIVE: force=false already serves the in-memory copy when present.
        if (typeof loadTrackRecord === 'function') loadTrackRecord(false);
    }
    // Watchlist loader
    if (page === 'watchlist') {
        if (typeof window.loadUserWatchlist === 'function') window.loadUserWatchlist(false);
    }
    // Kelola Keuangan worksheet: loads its runtime on first visit; later
    // visits keep the rows as the user left them.
    if (page === 'money-management') {
        if (typeof window.initMoneyManagement === 'function') window.initMoneyManagement();
    }
}

setRoute.text:
function setRoute(path, replace) {
    if (!window.history) return;
    var currentFull = (window.location.pathname || '') + (window.location.search || '');
    if (currentFull === path) return;
    if (window.location.pathname.startsWith('/preview/') && !path.startsWith('/preview/')) return;
    if (replace) window.history.replaceState({ path: path }, '', path);
    else window.history.pushState({ path: path }, '', path);
}

switchScreenerType.text:
function switchScreenerType(type) {
    _currentScreenerType = type;
    if (window.AutoCuanScreenerV2 && typeof window.AutoCuanScreenerV2.syncModeSlots === 'function') {
        window.AutoCuanScreenerV2.syncModeSlots(type);
    }
    var kongloPane = document.getElementById('screenerKongloPane');
    var nkPane = document.getElementById('screenerNonKongloPane');
    var dtPane = document.getElementById('screenerDayTradePane');
    var btnKonglo = document.getElementById('scrTypeKonglo');
    var btnNk = document.getElementById('scrTypeNonKonglo');
    var btnDt = document.getElementById('scrTypeDayTrade');

    // The two appearances are one class plus a state, not two hand-written
    // utility strings. Assigning .className still replaces the whole attribute,
    // exactly as before, so the switching behaviour is unchanged.
    var activeClass = 'ac-segment is-active on';
    var inactiveClass = 'ac-segment';
    var ind = document.getElementById('scrTypeInd');
    if (ind) ind.className = 'ind' + (type === 'nonkonglo' ? ' k1' : (type === 'daytrade' ? ' k2' : ''));
    var desc = document.getElementById('scrModeDesc');
    if (desc) desc.textContent = SCREENER_MODE_DESC[type] || SCREENER_MODE_DESC.konglo;

    // Hide all panes
    if (kongloPane) kongloPane.classList.add('hidden');
    if (nkPane) nkPane.classList.add('hidden');
    if (dtPane) dtPane.classList.add('hidden');

    // Reset all buttons. aria-pressed moves with the class so a screen reader
    // is told which segment is current, not just shown it.
    [btnKonglo, btnNk, btnDt].forEach(function (btn) {
        if (!btn) return;
        btn.className = inactiveClass;
        btn.setAttribute('aria-pressed', 'false');
    });

    // Stop all pollings
    stopScreenerPolling();
    stopNkPolling();
    stopDtPolling();

    if (type === 'konglo') {
        if (kongloPane) { kongloPane.classList.remove('hidden'); kongloPane.classList.remove('scr-pane-anim'); void kongloPane.offsetWidth; kongloPane.classList.add('scr-pane-anim'); }
        if (btnKonglo) { btnKonglo.className = activeClass; btnKonglo.setAttribute('aria-pressed', 'true'); }
        loadSwingScreener();
        startScreenerPolling();
    } else if (type === 'nonkonglo') {
        if (nkPane) { nkPane.classList.remove('hidden'); nkPane.classList.remove('scr-pane-anim'); void nkPane.offsetWidth; nkPane.classList.add('scr-pane-anim'); }
        if (btnNk) { btnNk.className = activeClass; btnNk.setAttribute('aria-pressed', 'true'); }
        loadNkScreenerResults();
    } else if (type === 'daytrade') {
        if (dtPane) { dtPane.classList.remove('hidden'); dtPane.classList.remove('scr-pane-anim'); void dtPane.offsetWidth; dtPane.classList.add('scr-pane-anim'); }
        if (btnDt) { btnDt.className = activeClass; btnDt.setAttribute('aria-pressed', 'true'); }
        loadDayTradeScreener();
    }
}

toggleSektorView.text:
function toggleSektorView(viewType) {
    var tblWrap = document.getElementById('sektorTableWrap');
    var gridWrap = document.getElementById('sektorGroupsGrid');
    var btnTbl = document.getElementById('sektorBtnTable');
    var btnGrd = document.getElementById('sektorBtnGrid');
    var prov = document.getElementById('sektorHeatmapProv');
    var ind = document.getElementById('sektorViewInd');
    if (!tblWrap || !gridWrap) return;

    if (viewType === 'grid' || viewType === 'heatmap') {
        tblWrap.classList.add('hidden');
        tblWrap.style.display = 'none';
        gridWrap.classList.remove('hidden');
        gridWrap.style.display = 'grid';
        if (prov) prov.style.display = '';
        if (btnTbl) { btnTbl.classList.remove('is-active', 'on'); btnTbl.setAttribute('aria-pressed', 'false'); }
        if (btnGrd) { btnGrd.classList.add('is-active', 'on'); btnGrd.setAttribute('aria-pressed', 'true'); }
        if (ind) { ind.className = 'ind k1'; }
    } else {
        gridWrap.classList.add('hidden');
        gridWrap.style.display = 'none';
        if (prov) prov.style.display = 'none';
        tblWrap.classList.remove('hidden');
        tblWrap.style.display = '';
        if (btnGrd) { btnGrd.classList.remove('is-active', 'on'); btnGrd.setAttribute('aria-pressed', 'false'); }
        if (btnTbl) { btnTbl.classList.add('is-active', 'on'); btnTbl.setAttribute('aria-pressed', 'true'); }
        if (ind) { ind.className = 'ind k0'; }
    }
}

showGroupDetail.text:
async function showGroupDetail(groupCode) {
    var listView = document.getElementById('sektorListView');
    var detailView = document.getElementById('sektorDetailView');
    var header = document.getElementById('sektorDetailHeader');
    var table = document.getElementById('sektorDetailTable');
    var capEl = document.getElementById('sektorDetCap');
    var nfEl = document.getElementById('sektorDetNf');
    var pbvEl = document.getElementById('sektorDetPbv');
    var volEl = document.getElementById('sektorDetVol');
    var dateEl = document.getElementById('sektorDetDate');

    if (!detailView || !header || !table) return;

    listView.classList.add('hidden');
    detailView.classList.remove('hidden');
    detailView.style.display = 'flex';
    header.innerHTML = '<div class="text-center py-4"><div class="spinner"></div></div>';
    table.innerHTML = '';

    try {
        var response = await fetch('/api/sector-hot?group=' + encodeURIComponent(groupCode));
        var data = await response.json();

        if (!data.success || !data.group) {
            header.innerHTML = '<p class="text-sm text-gray-500">Data grup belum tersedia.</p>';
            return;
        }

        var g = data.group;
        var members = data.members || [];
        var memberCnt = g.stock_count != null ? g.stock_count : (g.member_count != null ? g.member_count : (members.length > 0 ? members.length : null));
        var memberCntDisplay = (memberCnt != null && !isNaN(Number(memberCnt))) ? String(memberCnt) : '—';
        var groupTitle = g.group_name || ('Grup ' + (g.group_code || groupCode));
        var cleanCode = formatSektorCode(g.group_code || groupCode);
        var chgView = changeDisplay(g.avg_change_pct);
        var chgColor = chgView.cls;
        var avgDisplay = chgView.text;
        var volDisplay = g.avg_volume_ratio ? formatRatio(g.avg_volume_ratio) : '—';
        var flowInfo = getFlowBadge(g);

        header.innerHTML = '<div><div class="kick">Grup konglomerat · ' + escapeHtml(cleanCode) + '</div>' +
            '<h1>' + escapeHtml(groupTitle) + '</h1>' +
            '<p>Rerata harian <b class="' + chgColor + '">' + avgDisplay + '</b> · ' + memberCntDisplay + ' emiten · aliran ' + escapeHtml(flowInfo.text.toLowerCase()) + '</p></div>' +
            '<a class="btn" href="#screener" onclick="if(typeof navigateTo===\'function\')navigateTo(\'screener\')">Saring di Screener</a>';

        if (capEl) capEl.textContent = g.market_cap ? formatTxValue(g.market_cap) : (g.cap || '—');
        if (nfEl) {
            if (g.net_foreign != null) {
                nfEl.textContent = formatTxValue(g.net_foreign);
                nfEl.className = 'big num pop ' + (g.net_foreign >= 0 ? 'pos' : 'neg');
            } else if (g.net_flow != null && g.net_flow !== 0) {
                nfEl.textContent = (g.net_flow >= 0 ? '+' : '−') + formatTxValue(Math.abs(g.net_flow));
                nfEl.className = 'big num pop ' + (g.net_flow >= 0 ? 'pos' : 'neg');
            } else {
                nfEl.textContent = g.nf || '—';
                nfEl.className = 'big num pop';
            }
        }
        if (pbvEl) pbvEl.textContent = (g.pbv || g.avg_pbv) ? (typeof (g.pbv || g.avg_pbv) === 'number' ? (g.pbv || g.avg_pbv).toFixed(2).replace('.', ',') + '×' : (g.pbv || g.avg_pbv)) : '—';
        if (volEl) volEl.textContent = volDisplay;
        if (dateEl) {
            if (g.calculated_at) {
                var dt = new Date(g.calculated_at);
                dateEl.textContent = dt.toLocaleDateString('id-ID', { timeZone: 'Asia/Jakarta', day: 'numeric', month: 'short', year: 'numeric' });
            } else {
                dateEl.textContent = '13 Okt 2026';
            }
        }

        if (members.length === 0) {
            table.innerHTML = '<div style="padding:28px 20px" class="mut">Daftar konstituen grup ini belum dimuat pada data contoh. Di produk, tabel ini diisi dari snapshot grup terbaru.</div>';
            return;
        }

        var tHtml = '<table class="tbl w-full text-xs border-collapse min-w-[760px]"><thead><tr>';
        tHtml += '<th>Ticker</th>';
        tHtml += '<th>Nama</th>';
        tHtml += '<th class="r">Harga</th>';
        tHtml += '<th class="r">Chg</th>';
        tHtml += '<th class="r">Vol/Avg</th>';
        tHtml += '<th>Bandar</th>';
        tHtml += '<th>Sinyal</th>';
        tHtml += '<th class="r"></th>';
        tHtml += '</tr></thead><tbody>';

        members.forEach(function(m, idx) {
            var hasData = m.last_price != null;
            var pctView = changeDisplay(hasData ? m.change_pct : null);
            var pctColor = pctView.cls;
            var pctDisplay = pctView.text;
            var priceDisplay = hasData ? formatPrice(m.last_price) : '<span class="text-gray-600">—</span>';
            var ratioDisplay = hasData ? formatRatio(m.volume_ratio_30d) : '—';
            var isAnchor = m.member_type === 'ANCHOR';
            var tickerLabel = isAnchor ? m.ticker + ' ★' : m.ticker;
            var bdrText = m.bandar_status || (m.change_pct > 2 ? 'Akumulasi kuat' : (m.change_pct > 0 ? 'Akumulasi' : (m.change_pct < -2 ? 'Distribusi besar' : 'Netral')));
            var bdrDot = m.change_pct > 0 ? 'dot g' : (m.change_pct < 0 ? 'dot r' : 'dot m');
            var sigText = m.signal || (isAnchor ? 'Anchor' : (m.change_pct > 3 ? 'Day trade' : (m.change_pct > 1 ? 'Swing ready' : 'Watchlist')));

            tHtml += '<tr class="border-b border-dark-600/20 hover:bg-dark-700/30 cursor-pointer rise d' + Math.min(idx, 11) + '" onclick="screenerTickerClick(\'' + escapeHtml(m.ticker) + '\')">';
            tHtml += '<td><span class="tk mono font-semibold">' + escapeHtml(tickerLabel) + '</span></td>';
            tHtml += '<td class="mut truncate max-w-[200px]">' + escapeHtml(m.stock_name || '—') + '</td>';
            tHtml += '<td class="r num mono" style="font-weight:600">' + priceDisplay + '</td>';
            tHtml += '<td class="r num ' + pctColor + '" style="font-weight:600">' + pctDisplay + '</td>';
            tHtml += '<td class="r num">' + ratioDisplay + '</td>';
            tHtml += '<td><span class="flow"><span class="' + bdrDot + '"></span>' + escapeHtml(bdrText) + '</span></td>';
            tHtml += '<td>' + escapeHtml(sigText) + '</td>';
            tHtml += '<td class="r"><a class="lnk" href="#analisis" onclick="event.stopPropagation(); if(typeof screenerTickerClick===\'function\')screenerTickerClick(\'' + escapeHtml(m.ticker) + '\');" style="font-size:12px">Riset</a></td>';
            tHtml += '</tr>';
        });
        tHtml += '</tbody></table>';
        table.innerHTML = tHtml;
    } catch (e) {
        header.innerHTML = '<p class="text-sm text-red-400">Gagal memuat detail grup.</p>';
    }
}

applyPremiumAccessUi.text:
function applyPremiumAccessUi() {
    syncHeaderUsername();
    var allowed=hasConfirmedPremiumAccess();
    document.querySelectorAll('[data-premium-nav="true"]').forEach(function(button){
        var isScreener = false;
        if (typeof button.getAttribute === 'function') {
            isScreener = button.getAttribute('data-sidebar-page') === 'screener' || button.getAttribute('data-page') === 'screener';
        } else if (button.id) {
            isScreener = button.id === 'nav-screener';
        }
        if (isScreener) {
            button.classList.remove('hidden'); button.disabled = false;
            button.setAttribute('aria-hidden', 'false'); if ('inert' in button) button.inert = false;
            return;
        }
        button.classList.toggle('hidden',!allowed); button.disabled=!allowed;
        button.setAttribute('aria-hidden',allowed?'false':'true'); if ('inert' in button) button.inert=!allowed;
    });
    if (typeof updateSidebarGroupVisibility === 'function') updateSidebarGroupVisibility();
    document.querySelectorAll('[data-premium-page="true"]').forEach(function(page){
        var isScreenerPage = (page && page.id === 'page-screener');
        if (allowed || (isScreenerPage && page.id === 'page-' + currentPage)) {
            page.removeAttribute('aria-hidden'); if ('inert' in page) page.inert=false;
            // A pending access check may have hidden the already selected page.
            // Restore only that page after a confirmed server approval; never
            // reveal other pages or bypass the ancestor maintenance/login gate.
            if (page.id === 'page-' + currentPage) page.classList.remove('hidden');
        }
        else { page.classList.add('hidden'); page.setAttribute('aria-hidden','true'); if ('inert' in page) page.inert=true; }
    });
    if (isDeniedWebsiteAccess() && isPremiumFeaturePage(currentPage)) {
        clearRenderedPremiumData();
        navigateTo('dashboard');
    }
}
